export function crearMotor(): MotorAudio | null {
  try {
    // require y no import: si el módulo nativo no está (Expo Go), la app sigue con el plan B (expo-audio)
    const api = require("react-native-audio-api") as typeof import("react-native-audio-api");
    const ctx = new api.AudioContext();
    return { ctx, decodificar: (modulo) => ctx.decodeAudioData(modulo) };
  } catch {
    return null;
  }
}

